/* ========================================
   PARADISE.EXE — CSS FOUNDATION
   ======================================== */

:root {
  /* Time-based color palette (defaults to evening) */
  --sky-deep: #0a0612;
  --sky-mid: #1a0f2e;
  --sky-horizon: #2d1b4e;
  --neon-pink: rgba(255, 180, 160, 0.7);
  --neon-gold: rgba(220, 200, 160, 0.7);
  --neon-amber: rgba(200, 180, 140, 0.7);
  --muted-red: #8b3a3a;
  --faded-teal: #2a6b7c;
  --dust-white: rgba(255, 245, 230, 0.6);
  --fog-color: rgba(20, 8, 40, 0.7);
  --grain-opacity: 0.04;
  --bloom-color: rgba(255, 180, 100, 0.15);
  --mood-accent: rgba(255, 180, 160, 0.7);
  --vinyl-speed: 3s;
  --scroll-progress: 0;
  --mouse-x: 0.5;
  --mouse-y: 0.5;
  --time-mode: "evening";
}

/* TIME MODE CLASSES */
body.time-late-night {
  --sky-deep: #020408;
  --sky-mid: #040d1a;
  --sky-horizon: #0a1628;
  --neon-pink: #7b4f8a;
  --fog-color: rgba(2, 4, 15, 0.85);
  --grain-opacity: 0.18;
}

body.time-morning {
  --sky-deep: #1a1208;
  --sky-mid: #2d2010;
  --sky-horizon: #4a3520;
  --neon-pink: #d4956b;
  --fog-color: rgba(20, 15, 5, 0.5);
  --grain-opacity: 0.08;
}

body.time-afternoon {
  --sky-deep: #1a0f08;
  --sky-mid: #2d1a0a;
  --sky-horizon: #5a3015;
  --neon-pink: #ff9d5c;
  --neon-gold: #ffcc44;
  --fog-color: rgba(25, 10, 5, 0.4);
}

body.time-evening {
  --sky-deep: #0a0612;
  --sky-mid: #1a0f2e;
  --sky-horizon: #3d1b4e;
}

*,
*::before,
*::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

html {
  overflow-x: hidden;
  scroll-behavior: smooth;
  overscroll-behavior: none;
}

body {
  font-family: "Inter", sans-serif;
  background: var(--sky-deep);
  color: var(--dust-white);
  overflow-x: hidden;
  overscroll-behavior: none;
  cursor: none;
}

/* CUSTOM CURSOR */
.cursor {
  position: fixed;
  width: 16px;
  height: 16px;
  border: 1px solid rgba(255, 107, 157, 0.7);
  border-radius: 50%;
  pointer-events: none;
  z-index: 9999;
}

/* GRAIN OVERLAY */
.grain {
  position: fixed;
  inset: -200%;
  width: 400%;
  height: 400%;
  z-index: 9990;
  pointer-events: none;
  opacity: 0.04;
  animation: grainShift 1.5s steps(1) infinite;
  will-change: transform;
  background-image: url("data:image/svg+xml,%3Csvg viewBox='0 0 512 512' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='noiseFilter'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='0.85' numOctaves='4' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23noiseFilter)'/%3E%3C/svg%3E");
  background-size: 256px 256px;
  mix-blend-mode: overlay;
}

@keyframes grainShift {
  0% {
    transform: translate(0, 0);
  }

  10% {
    transform: translate(-5%, -5%);
  }

  20% {
    transform: translate(-10%, 5%);
  }

  30% {
    transform: translate(5%, -10%);
  }

  40% {
    transform: translate(-5%, 15%);
  }

  50% {
    transform: translate(-10%, 5%);
  }

  60% {
    transform: translate(15%, 0);
  }

  70% {
    transform: translate(0, 10%);
  }

  80% {
    transform: translate(-15%, 0);
  }

  90% {
    transform: translate(10%, 5%);
  }

  100% {
    transform: translate(5%, 0);
  }
}

/* VHS SCANLINES */
.vhs-overlay,
.vhs-glitch,
.chroma-r,
.chroma-b {
  display: none !important;
}

/* ========================================
   LANDING / INTRO SCENE
   ======================================== */
#intro-scene {
  position: fixed;
  inset: 0;
  z-index: 1000;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  overflow: hidden;
  transition: opacity 1.5s ease;
  cursor: none;
}

/* SKY */
.intro-sky {
  position: absolute;
  inset: 0;
  background: #000000;
}

/* STARS */
.stars-layer {
  position: absolute;
  inset: 0;
  overflow: hidden;
}

.star {
  position: absolute;
  width: 1px;
  height: 1px;
  background: white;
  border-radius: 50%;
  animation: twinkle 3s ease-in-out infinite;
}

@keyframes twinkle {
  0%,
  100% {
    opacity: 0.3;
    transform: scale(1);
  }

  50% {
    opacity: 1;
    transform: scale(1.5);
  }
}

/* CLOUDS */
.clouds-layer {
  position: absolute;
  inset: 0;
  pointer-events: none;
}

.cloud {
  position: absolute;
  border-radius: 50%;
  filter: blur(40px);
  animation: cloudDrift linear infinite;
  opacity: 0.15;
}

@keyframes cloudDrift {
  from {
    transform: translateX(-200px);
  }

  to {
    transform: translateX(calc(100vw + 200px));
  }
}

/* HIGHWAY */
.highway-scene {
  position: absolute;
  bottom: 0;
  left: 0;
  right: 0;
  height: 55%;
  background: linear-gradient(
    to bottom,
    transparent 0%,
    #1a1a1a 40%,
    #222222 100%
  );
}

.highway-road {
  position: absolute;
  bottom: 0;
  left: 0;
  right: 0;
  height: 60%;
  background: linear-gradient(to top, #080608, #0f0c14, #160f25);
  overflow: hidden;
}

/* Road perspective lines */
.highway-road::before {
  content: "";
  position: absolute;
  bottom: 0;
  left: 50%;
  transform: translateX(-50%);
  width: 0;
  height: 0;
  border-left: 4vw solid transparent;
  border-right: 4vw solid transparent;
  border-bottom: 35vw solid rgba(255, 200, 80, 0.08);
}

/* Dashed center line */
.road-lines {
  position: absolute;
  bottom: 0;
  left: 50%;
  transform: translateX(-50%);
  display: flex;
  flex-direction: column-reverse;
  align-items: center;
  gap: 3vw;
  height: 100%;
  overflow: hidden;
  animation: roadMove 0.8s linear infinite;
}

@keyframes roadMove {
  from {
    transform: translateX(-50%) translateY(0);
  }

  to {
    transform: translateX(-50%) translateY(6vw);
  }
}

.road-dash {
  width: 0.4vw;
  background: rgba(255, 200, 80, 0.4);
  border-radius: 2px;
  flex-shrink: 0;
}

/* HORIZON GLOW */
.horizon-glow {
  position: absolute;
  bottom: 32%;
  left: 0;
  right: 0;
  height: 120px;
  background: linear-gradient(to top, rgba(255, 255, 255, 0.03), transparent);
  filter: blur(20px);
}

/* CADILLAC SILHOUETTE */
.cadillac {
  position: absolute;
  bottom: calc(32%);
  left: 20%;
  transform: translateX(-50%);
  opacity: 1;
  filter: drop-shadow(0 4px 12px rgba(0, 0, 0, 0.6));
}

.cadillac-body {
  width: 140px;
  height: 30px;
  background: linear-gradient(to right, #d0d0d0, #ffffff, #d0d0d0);
  border-radius: 4px 8px 0 0;
  position: relative;
}

.cadillac-roof {
  position: absolute;
  top: -22px;
  left: 20px;
  right: 25px;
  height: 22px;
  background: linear-gradient(to right, #c0c0c0, #e8e8e8, #c0c0c0);
  border-radius: 6px 8px 0 0;
  border-top: 1px solid rgba(255, 255, 255, 0.3);
}

.cadillac-hood {
  position: absolute;
  right: -30px;
  top: 5px;
  width: 30px;
  height: 15px;
  background: linear-gradient(to right, #e0e0e0, #d0d0d0);
  border-radius: 0 4px 0 0;
}

.cadillac-trunk {
  position: absolute;
  left: -20px;
  top: 8px;
  width: 20px;
  height: 12px;
  background: #d0d0d0;
  border-radius: 2px 0 0 0;
}

.cadillac-wheel {
  position: absolute;
  bottom: -8px;
  width: 22px;
  height: 22px;
  background: radial-gradient(
    circle,
    #888 40%,
    #333 40%,
    #333 60%,
    #666 60%,
    #888 70%,
    #333 70%
  );
  border-radius: 50%;
  border: 2px solid #999;
}

.cadillac-wheel.front {
  right: 15px;
}

.cadillac-wheel.back {
  left: 15px;
}

.cadillac-light-front {
  position: absolute;
  right: -32px;
  top: 12px;
  width: 4px;
  height: 6px;
  background: rgba(255, 220, 150, 0.9);
  box-shadow: 0 0 8px rgba(255, 240, 200, 0.3);
  border-radius: 0 2px 2px 0;
}

.cadillac-shadow {
  position: absolute;
  bottom: -6px;
  left: 10%;
  right: 10%;
  height: 6px;
  background: radial-gradient(ellipse, rgba(0, 0, 0, 0.4), transparent);
  border-radius: 50%;
}

/* FOG LAYERS */
.fog-layer {
  position: absolute;
  left: -10%;
  right: -10%;
  height: 120px;
  background: linear-gradient(to top, var(--fog-color), transparent);
  filter: blur(20px);
  pointer-events: none;
  animation: fogDrift 8s ease-in-out infinite;
}

@keyframes fogDrift {
  0%,
  100% {
    transform: translateX(0) scaleY(1);
  }

  50% {
    transform: translateX(20px) scaleY(1.1);
  }
}

/* DUST PARTICLES */
.particles-canvas {
  position: fixed;
  inset: 0;
  z-index: 5;
  pointer-events: none;
}

/* INTRO TEXT */
.intro-content {
  position: relative;
  z-index: 10;
  text-align: center;
  top: -8vh;
}

.intro-title {
  font-family: "Playfair Display", serif;
  font-size: clamp(3rem, 10vw, 8rem);
  font-weight: 700;
  font-style: italic;
  letter-spacing: 0.2em;
  color: transparent;
  background: linear-gradient(135deg, #ffd700, #ff8c42, #ff6b9d, #ffd700);
  -webkit-background-clip: text;
  background-clip: text;
  text-shadow: 0 2px 20px rgba(255, 220, 180, 0.15);
  filter: none;
  opacity: 0;
  transform: translateY(20px);
  animation: titleReveal 3s ease forwards 1s;
}

@keyframes titleReveal {
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

.intro-sub {
  font-family: "Inter", sans-serif;
  font-weight: 100;
  font-size: clamp(0.7rem, 2vw, 1.1rem);
  letter-spacing: 0.6em;
  text-transform: uppercase;
  color: rgba(255, 220, 180, 0.6);
  margin-top: 1.5rem;
  opacity: 0;
  animation: fadeUp 2s ease forwards 2.5s;
}

@keyframes fadeUp {
  from {
    opacity: 0;
    transform: translateY(15px);
  }

  to {
    opacity: 1;
    transform: translateY(0);
  }
}

.enter-btn {
  margin-top: 3rem;
  padding: 14px 50px;
  background: rgba(255, 255, 255, 0.05);
  border: 0.5px solid rgba(255, 255, 255, 0.2);
  box-shadow: 0 1px 20px rgba(255, 255, 255, 0.05);
  color: rgba(255, 220, 200, 0.9);
  font-family: "Inter", sans-serif;
  font-weight: 200;
  font-size: 0.8rem;
  letter-spacing: 0.4em;
  text-transform: uppercase;
  cursor: none;
  border-radius: 1px;
  backdrop-filter: blur(10px);
  transition: all 0.6s ease;
  opacity: 0;
  animation: fadeUp 2s ease forwards 3.5s;
  position: relative;
  overflow: hidden;
  display: inline-block;
}

.enter-btn::before {
  content: "";
  position: absolute;
  inset: 0;
  background: linear-gradient(
    135deg,
    transparent,
    rgba(255, 255, 255, 0.05),
    transparent
  );
  transform: translateX(-100%);
  transition: transform 0.6s ease;
}

.enter-btn:hover {
  background: rgba(255, 255, 255, 0.08);
  border-color: rgba(255, 255, 255, 0.4);
  box-shadow: none;
}

.enter-btn:hover::before {
  transform: translateX(100%);
}

/* LIGHT SHAFT FROM MOUSE */
.light-shaft {
  position: absolute;
  inset: 0;
  pointer-events: none;
  background: radial-gradient(
    ellipse 40% 60% at 50% 50%,
    rgba(255, 255, 255, 0.04),
    transparent
  );
  opacity: 0.04;
  transition: background 0.3s ease;
}

/* ========================================
   MAIN WORLD CONTAINER
   ======================================== */
#main-world {
  position: relative;
  opacity: 0;
  min-height: 100vh;
}

/* WORLD HEADER */
.world-header {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  z-index: 500;
  padding: 20px 40px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  background: linear-gradient(to bottom, rgba(5, 3, 15, 0.8), transparent);
  backdrop-filter: blur(4px);
  pointer-events: none;
  border-bottom: 0.5px solid rgba(255, 255, 255, 0.08);
}

.header-logo {
  font-family: "Playfair Display", serif;
  font-style: italic;
  font-size: 1.2rem;
  letter-spacing: 0.15em;
  color: rgba(255, 200, 150, 0.8);
  pointer-events: all;
}

.header-nav {
  display: flex;
  gap: 30px;
  align-items: center;
  pointer-events: all;
}

.header-nav a {
  font-family: "Inter", sans-serif;
  font-weight: 200;
  font-size: 0.65rem;
  letter-spacing: 0.3em;
  text-transform: uppercase;
  color: rgba(255, 220, 200, 0.5);
  text-decoration: none;
  transition: color 0.3s ease;
}

.header-nav a:hover {
  color: rgba(255, 180, 120, 0.9);
}

.header-time {
  font-family: "Inter", sans-serif;
  font-weight: 100;
  font-size: 0.65rem;
  letter-spacing: 0.2em;
  color: rgba(255, 200, 150, 0.4);
  pointer-events: all;
}

/* MOOD SELECTOR */
.mood-panel {
  position: fixed;
  bottom: 30px;
  left: 30px;
  z-index: 500;
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.mood-label {
  font-family: "Inter", sans-serif;
  font-weight: 100;
  font-size: 0.55rem;
  letter-spacing: 0.3em;
  text-transform: uppercase;
  color: rgba(255, 200, 150, 0.4);
  margin-bottom: 4px;
}

.mood-tag {
  padding: 5px 14px;
  background: rgba(255, 255, 255, 0.04);
  border: 1px solid rgba(255, 255, 255, 0.1);
  border-radius: 20px;
  font-family: "Inter", sans-serif;
  font-weight: 200;
  font-size: 0.6rem;
  letter-spacing: 0.2em;
  color: rgba(255, 200, 150, 0.6);
  cursor: none;
  transition: all 0.3s ease;
  backdrop-filter: blur(6px);
}

.mood-tag.active,
.mood-tag:hover {
  background: rgba(255, 107, 157, 0.15);
  border-color: rgba(255, 107, 157, 0.5);
  color: rgba(255, 180, 200, 0.9);
  box-shadow: 0 0 15px rgba(255, 107, 157, 0.2);
}

/* NOW PLAYING */
.now-playing {
  position: fixed;
  bottom: 30px;
  right: 30px;
  z-index: 500;
  width: 280px;
  background: var(--album-bg, #0a0a0a);
  border: 0.5px solid rgba(255, 255, 255, 0.1);
  backdrop-filter: none;
  border-radius: 2px;
  padding: 16px;
  overflow: hidden;
}

.now-playing::before {
  content: "";
  position: absolute;
  inset: 0;
  background: linear-gradient(
    135deg,
    rgba(255, 180, 100, 0.03),
    rgba(255, 107, 157, 0.03)
  );
  pointer-events: none;
}

.np-label {
  font-family: "Inter", sans-serif;
  font-weight: 100;
  font-size: 0.5rem;
  letter-spacing: 0.4em;
  text-transform: uppercase;
  color: rgba(255, 200, 150, 0.4);
  margin-bottom: 12px;
}

.np-title {
  font-family: "Cormorant Garamond", serif;
  font-style: italic;
  font-size: 1.1rem;
  color: rgba(255, 220, 180, 0.9);
  line-height: 1.3;
  margin-bottom: 4px;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  max-width: 160px;
}

.np-album {
  font-family: "Inter", sans-serif;
  font-weight: 200;
  font-size: 0.6rem;
  letter-spacing: 0.2em;
  color: rgba(255, 180, 120, 0.5);
}

.np-progress {
  margin-top: 12px;
  height: 1px;
  background: rgba(255, 255, 255, 0.1);
  border-radius: 1px;
  overflow: hidden;
}

.np-progress-bar {
  height: 100%;
  width: 0%;
  background: linear-gradient(to right, var(--neon-amber), var(--neon-pink));
  transition: width 0.5s ease;
  box-shadow: 0 0 8px rgba(255, 150, 100, 0.5);
}

.np-controls {
  display: flex;
  align-items: center;
  gap: 16px;
  margin-top: 12px;
}

.np-btn {
  background: none;
  border: none;
  cursor: none;
  color: rgba(255, 200, 150, 0.6);
  font-size: 1rem;
  transition:
    color 0.2s ease,
    transform 0.2s ease;
  padding: 2px;
}

.np-btn:hover {
  color: rgba(255, 200, 150, 1);
  transform: scale(1.2);
}

.np-vinyl-mini {
  width: 32px;
  height: 32px;
  border-radius: 50%;
  background: radial-gradient(
    circle at 50% 50%,
    #111 20%,
    #1a1a1a 20%,
    #222 30%,
    #111 30%,
    #1a1a1a 40%,
    #222 50%,
    #111 50%,
    #1a1a1a 60%,
    #222 70%,
    #111 70%
  );
  border: 2px solid #333;
  animation: vinylSpin 3s linear infinite paused;
  flex-shrink: 0;
  position: relative;
}

.np-vinyl-mini.playing {
  animation-play-state: running;
}

.np-vinyl-mini::after {
  content: "";
  position: absolute;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%);
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: radial-gradient(circle, var(--neon-pink), #333);
}

@keyframes vinylSpin {
  from {
    transform: rotate(0deg);
  }

  to {
    transform: rotate(360deg);
  }
}

/* ========================================
   WORLD SECTIONS
   ======================================== */
.world-section {
  min-height: 100vh;
  position: relative;
  overflow: hidden;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: flex-start;
  padding: 120px 60px 80px;
  contain: layout style;
}

/* Section atmospheres */
.world-btd {
  background: linear-gradient(180deg, #0a1628 0%, #0d1f3c 50%, #f0f4ff 100%);
}

#paradise-ep {
  background: linear-gradient(
    180deg,
    #1a1200 0%,
    #2d1f00 50%,
    #c8960a 100%
  ) !important;
}

.world-uv {
  background: linear-gradient(180deg, #000000 0%, #111111 50%, #2a2a2a 100%);
}

.world-honey {
  background: linear-gradient(180deg, #1a0000 0%, #0a0020 50%, #1a0010 100%);
}

.world-lfl {
  background: linear-gradient(180deg, #001a18 0%, #003028 50%, #004a3a 100%);
}

.world-nfr {
  background: linear-gradient(180deg, #1a1a00 0%, #0a1400 50%, #1a0000 100%);
}

#chemtrails {
  background: linear-gradient(
    180deg,
    #141414 0%,
    #1e1e1e 50%,
    #282828 100%
  ) !important;
}

.world-tunnel {
  background: linear-gradient(180deg, #1a1a00 0%, #141400 50%, #c8b400 100%);
}

.world-heaven {
  background: linear-gradient(180deg, #15230f 0%, #172511 50%, #0f160b 100%);
}

.section-atmosphere {
  position: absolute;
  inset: 0;
  pointer-events: none;
}

/* World title */
.world-title {
  font-family: "Playfair Display", serif;
  font-style: italic;
  font-size: clamp(2.5rem, 6vw, 5rem);
  font-weight: 400;
  letter-spacing: 0.08em;
  line-height: 1.1;
  text-align: center;
  position: relative;
  z-index: 2;
  margin-bottom: 8px;
}

.world-subtitle {
  font-family: "Inter", sans-serif;
  font-weight: 100;
  font-size: 0.65rem;
  letter-spacing: 0.5em;
  text-transform: uppercase;
  opacity: 0.5;
  text-align: center;
  position: relative;
  z-index: 2;
  margin-bottom: 60px;
}

/* BTD specific */
.world-btd .world-title {
  color: #d4a574;
  text-shadow: 0 2px 30px rgba(0, 0, 0, 0.8);
}

/* UV specific */
.world-uv .world-title {
  color: #b8c4d4;
  text-shadow: 0 2px 30px rgba(0, 0, 0, 0.8);
}

/* NFR specific */
.world-nfr .world-title {
  color: #d4aa6a;
  text-shadow: 0 2px 30px rgba(0, 0, 0, 0.8);
}

/* Honey specific */
.world-honey .world-title {
  color: #8fb8d4;
  text-shadow: 0 2px 30px rgba(0, 0, 0, 0.8);
}

/* LFL specific */
.world-lfl .world-title {
  color: #d490b0;
  text-shadow: 0 2px 30px rgba(0, 0, 0, 0.8);
}

/* Heaven specific */
.world-heaven .world-title {
  color: #d4d0c0;
  text-shadow: 0 2px 30px rgba(0, 0, 0, 0.8);
}

/* ========================================
   VINYL RECORD SYSTEM
   ======================================== */
.vinyl-grid {
  display: flex;
  flex-wrap: wrap;
  gap: 40px;
  justify-content: center;
  align-items: flex-start;
  position: relative;
  z-index: 2;
  width: 100%;
  animation: fadeIn 0.6s ease;
}

@keyframes fadeIn {
  from {
    opacity: 0;
    transform: translateY(10px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

.vinyl-card {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 16px;
  cursor: none;
  transition: transform 0.4s ease;
  contain: layout style;
  touch-action: manipulation;
}

.vinyl-card:hover {
  transform: translateY(-8px);
  box-shadow: 0 8px 32px rgba(0, 0, 0, 0.4);
}

.vinyl-wrapper {
  position: relative;
  width: 120px;
  height: 120px;
}

.vinyl-disc {
  width: 120px;
  height: 120px;
  border-radius: 50%;
  position: relative;
  cursor: none;
  transform-origin: center;
  transition: box-shadow 0.3s ease;
  touch-action: none;
}

.vinyl-disc:hover {
  box-shadow: 0 0 20px rgba(255, 255, 255, 0.06);
}

.vinyl-disc.spinning {
  animation: vinylSpin var(--vinyl-speed) linear infinite;
  will-change: transform;
  box-shadow: 0 2px 12px rgba(0, 0, 0, 0.5);
}

.vinyl-disc.dragging {
  animation: none !important;
  cursor: none;
}

/* Vinyl canvas — rendered at 2× for crispness */
.vinyl-canvas {
  width: 100%;
  height: 100%;
  border-radius: 50%;
  display: block;
}

/* Deep physical shadow under each record */
.vinyl-wrapper {
  position: relative;
  width: 120px;
  height: 120px;
  filter: drop-shadow(0 8px 18px rgba(0, 0, 0, 0.85))
    drop-shadow(0 2px 6px rgba(0, 0, 0, 0.7));
}

/* Vinyl info */
.vinyl-info {
  text-align: center;
  width: 140px;
}

.vinyl-song-name {
  font-family: "Cormorant Garamond", serif;
  font-style: italic;
  font-size: 0.85rem;
  color: rgba(255, 220, 180, 0.85);
  line-height: 1.3;
  margin-bottom: 4px;
}

.vinyl-mood-tag {
  display: none;
  font-family: "Inter", sans-serif;
  font-weight: 200;
  font-size: 0.5rem;
  letter-spacing: 0.2em;
  text-transform: uppercase;
  color: rgba(255, 180, 120, 0.4);
}

.vinyl-play-count {
  font-family: "Inter", sans-serif;
  font-weight: 100;
  font-size: 0.5rem;
  letter-spacing: 0.15em;
  color: rgba(255, 180, 120, 0.3);
  margin-top: 4px;
}

.vinyl-fav-btn {
  display: none;
  background: none;
  border: none;
  cursor: none;
  font-size: 0.8rem;
  color: rgba(255, 100, 150, 0.3);
  transition: all 0.3s ease;
  margin-top: 4px;
  display: block;
  margin: 4px auto 0;
}

.vinyl-fav-btn.active {
  color: rgba(255, 255, 255, 0.8);
  text-shadow: none;
}

/* ========================================
   BTD WORLD DECORATIONS
   ======================================== */
.btd-roses {
  position: absolute;
  pointer-events: none;
}

.btd-rose {
  position: absolute;
  font-size: 1.5rem;
  animation: roseFloat 6s ease-in-out infinite;
  opacity: 0.3;
}

@keyframes roseFloat {
  0%,
  100% {
    transform: translateY(0) rotate(0deg);
  }

  50% {
    transform: translateY(-15px) rotate(5deg);
  }
}

.btd-flag {
  position: absolute;
  right: 5%;
  top: 20%;
  width: 60px;
  height: 40px;
  background: linear-gradient(
    to bottom,
    #8b0000 0%,
    #8b0000 33%,
    rgba(220, 220, 200, 0.4) 33%,
    rgba(220, 220, 200, 0.4) 66%,
    #00008b 66%
  );
  opacity: 0.15;
  animation: flagWave 3s ease-in-out infinite;
  transform-origin: left center;
}

@keyframes flagWave {
  0%,
  100% {
    transform: skewY(0deg);
  }

  50% {
    transform: skewY(3deg);
  }
}

/* ========================================
   UV WORLD — RAIN & NEON
   ======================================== */
.rain-canvas {
  position: absolute;
  inset: 0;
  pointer-events: none;
  opacity: 0.4;
}

.uv-motel {
  display: none !important;
}

@keyframes neonFlicker {
  0%,
  90%,
  94%,
  98%,
  100% {
    opacity: 1;
  }

  92%,
  96% {
    opacity: 0.3;
  }
}

/* UV puddle reflection */
.puddle {
  position: absolute;
  bottom: 15%;
  left: 25%;
  width: 200px;
  height: 60px;
  background: radial-gradient(ellipse, rgba(100, 150, 255, 0.15), transparent);
  border-radius: 50%;
  transform: scaleY(0.3);
  filter: blur(3px);
  animation: puddleShimmer 2s ease-in-out infinite;
}

@keyframes puddleShimmer {
  0%,
  100% {
    opacity: 0.6;
  }

  50% {
    opacity: 1;
  }
}

/* ========================================
   NFR WORLD — CALIFORNIA WARMTH
   ======================================== */
.nfr-sunset {
  position: absolute;
  inset: 0;
  pointer-events: none;
  background: radial-gradient(
    ellipse 80% 50% at 50% 0%,
    rgba(255, 150, 50, 0.15),
    transparent
  );
}

.nfr-ocean {
  position: absolute;
  bottom: 0;
  left: 0;
  right: 0;
  height: 25%;
  background: linear-gradient(
    to top,
    rgba(30, 60, 100, 0.8),
    rgba(30, 60, 100, 0.2),
    transparent
  );
  overflow: hidden;
}

.wave {
  position: absolute;
  width: 200%;
  left: -50%;
  height: 60px;
  background: rgba(50, 100, 150, 0.3);
  border-radius: 50%;
  animation: waveMove 4s ease-in-out infinite;
}

.wave:nth-child(2) {
  animation-delay: -2s;
  opacity: 0.6;
  top: 20px;
}

@keyframes waveMove {
  0%,
  100% {
    transform: translateX(0) translateY(0);
  }

  50% {
    transform: translateX(-5%) translateY(-10px);
  }
}

/* ========================================
   HONEYMOON WORLD — HOTEL POOL
   ======================================== */
.pool-shimmer {
  position: absolute;
  bottom: 0;
  left: 0;
  right: 0;
  height: 30%;
  background: linear-gradient(
    to top,
    rgba(30, 80, 120, 0.6),
    rgba(40, 100, 140, 0.3),
    transparent
  );
  overflow: hidden;
}

.pool-light {
  position: absolute;
  width: 100%;
  height: 2px;
  background: rgba(100, 200, 255, 0.3);
  animation: poolLight 3s ease-in-out infinite;
}

@keyframes poolLight {
  0% {
    transform: scaleX(0.5) translateY(0);
    opacity: 0;
  }

  50% {
    transform: scaleX(1) translateY(20px);
    opacity: 1;
  }

  100% {
    transform: scaleX(0.3) translateY(40px);
    opacity: 0;
  }
}

.palm-tree {
  position: absolute;
  bottom: 25%;
  pointer-events: none;
}

.palm-trunk {
  width: 8px;
  margin: 0 auto;
  background: linear-gradient(to top, #3d2b1f, #5c4033);
  border-radius: 4px 4px 0 0;
}

.palm-leaf {
  position: absolute;
  bottom: 100%;
  left: 50%;
  width: 50px;
  height: 15px;
  background: linear-gradient(to right, #2d5a27, #4a8a3f);
  border-radius: 0 50% 50% 0;
  transform-origin: left center;
}

/* ========================================
   FLOATING TEXT SYSTEM
   ======================================== */
.floating-text-container {
  position: absolute;
  inset: 0;
  pointer-events: none;
  overflow: hidden;
}

.floating-phrase {
  position: absolute;
  font-family: "Cormorant Garamond", serif;
  font-style: italic;
  color: rgba(255, 220, 180, 0.15);
  white-space: nowrap;
  animation: phraseFloat linear infinite;
}

@keyframes phraseFloat {
  from {
    transform: translateY(100vh);
    opacity: 0;
  }

  10% {
    opacity: 1;
  }

  90% {
    opacity: 1;
  }

  to {
    transform: translateY(-100px);
    opacity: 0;
  }
}

/* ========================================
   PLAYER / VINYL DETAIL VIEW
   ======================================== */
#vinyl-player {
  position: fixed;
  inset: 0;
  z-index: 800;
  display: flex;
  align-items: center;
  justify-content: center;
  background: rgba(0, 0, 0, 0.6);
  backdrop-filter: blur(8px);
  -webkit-backdrop-filter: blur(8px);
  opacity: 0;
  pointer-events: none;
  transition: opacity 0.4s ease;
}

#vinyl-player.open {
  opacity: 1;
  pointer-events: all;
}

.player-inner {
  display: flex;
  gap: 60px;
  align-items: center;
  padding: 40px;
  max-width: 900px;
  width: 90%;
  background: var(--album-bg, #0a0a0a);
  backdrop-filter: none;
  box-shadow: none;
  border: 0.5px solid rgba(255, 255, 255, 0.1);
}

.player-vinyl-large {
  width: 280px;
  height: 280px;
  border-radius: 50%;
  flex-shrink: 0;
  position: relative;
  cursor: none;
  filter: drop-shadow(0 20px 50px rgba(0, 0, 0, 0.9))
    drop-shadow(0 6px 16px rgba(0, 0, 0, 0.8))
    drop-shadow(0 0 40px rgba(255, 130, 80, 0.18))
    drop-shadow(0 0 80px rgba(255, 80, 140, 0.1));
}

.player-vinyl-canvas {
  width: 100%;
  height: 100%;
}

.player-info {
  flex: 1;
  min-width: 0;
}

.player-song {
  font-family: "Playfair Display", serif;
  font-style: italic;
  font-size: 2.2rem;
  color: rgba(255, 220, 180, 0.95);
  line-height: 1.2;
  margin-bottom: 8px;
  text-shadow: none;
}

.player-album {
  font-family: "Inter", sans-serif;
  font-weight: 200;
  font-size: 0.7rem;
  letter-spacing: 0.3em;
  color: rgba(255, 180, 120, 0.5);
  margin-bottom: 30px;
}

.player-progress-wrap {
  position: relative;
  height: 2px;
  background: rgba(255, 255, 255, 0.15);
  border-radius: 1px;
  cursor: none;
  margin-bottom: 16px;
}

.player-progress-fill {
  position: absolute;
  top: 0;
  left: 0;
  height: 100%;
  background: var(--album-accent);
  opacity: 0.8;
  border-radius: 1px;
  width: 0%;
  box-shadow: none;
}

.player-progress-dot {
  position: absolute;
  top: 50%;
  transform: translate(-50%, -50%);
  width: 10px;
  height: 10px;
  border-radius: 50%;
  background: #ffffff;
  box-shadow: 0 0 6px rgba(255, 255, 255, 0.2);
  left: 0%;
}

.player-time {
  display: flex;
  justify-content: space-between;
  font-family: "Inter", sans-serif;
  font-weight: 100;
  font-size: 0.65rem;
  letter-spacing: 0.15em;
  color: rgba(255, 200, 150, 0.4);
  margin-bottom: 30px;
}

.player-controls {
  display: flex;
  align-items: center;
  gap: 24px;
  margin-bottom: 30px;
}

.player-btn {
  background: none;
  border: none;
  cursor: none;
  color: rgba(255, 200, 150, 0.6);
  font-size: 1.4rem;
  transition: all 0.3s ease;
}

.player-btn:hover {
  color: rgba(255, 200, 150, 1);
  transform: scale(1.2);
}

.player-btn.play-btn {
  width: 56px;
  height: 56px;
  border-radius: 50%;
  background: rgba(255, 255, 255, 0.08);
  border: 0.5px solid rgba(255, 255, 255, 0.2);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.2rem;
  box-shadow: 0 2px 12px rgba(0, 0, 0, 0.4);
}

.player-btn.play-btn:hover {
  background: rgba(255, 255, 255, 0.15);
  box-shadow: 0 4px 20px rgba(0, 0, 0, 0.5);
}

.player-scrub-hint {
  font-family: "Inter", sans-serif;
  font-weight: 100;
  font-size: 0.6rem;
  letter-spacing: 0.3em;
  text-transform: uppercase;
  color: rgba(255, 200, 150, 0.3);
}

.player-note-area {
  margin-top: 20px;
}

.player-note {
  width: 100%;
  background: rgba(255, 255, 255, 0.03);
  border: 0.5px solid rgba(255, 255, 255, 0.1);
  border-radius: 2px;
  color: rgba(255, 220, 180, 0.7);
  font-family: "Cormorant Garamond", serif;
  font-style: italic;
  font-size: 0.95rem;
  padding: 12px;
  resize: none;
  outline: none;
  min-height: 70px;
  transition: border-color 0.3s ease;
  line-height: 1.5;
}

.player-note:focus {
  border-color: rgba(255, 107, 157, 0.3);
}

.player-note::placeholder {
  color: rgba(255, 200, 150, 0.2);
}

.player-close {
  position: absolute;
  top: 30px;
  right: 30px;
  background: none;
  border: none;
  cursor: none;
  color: rgba(255, 200, 150, 0.4);
  font-size: 1.5rem;
  transition: all 0.3s ease;
}

.player-close:hover {
  color: rgba(255, 200, 150, 0.9);
  transform: rotate(90deg);
}

/* ========================================
   SCROLLING ATMOSPHERE
   ======================================== */
.section-parallax-bg {
  position: absolute;
  inset: -20%;
  pointer-events: none;
  will-change: transform;
}

/* ========================================
   AMBIENT VISUALIZER
   ======================================== */
.ambient-viz {
  position: fixed;
  bottom: 0;
  left: 0;
  right: 0;
  height: 60px;
  z-index: 490;
  pointer-events: none;
  display: flex;
  align-items: flex-end;
  gap: 2px;
  padding: 0 8px;
  opacity: 0.3;
}

.viz-bar {
  flex: 1;
  background: rgba(255, 255, 255, 0.15);
  border-radius: 1px 1px 0 0;
  transition: height 0.1s ease;
}

/* ========================================
   HEAVEN / TUNNEL SPECIAL SECTIONS
   ======================================== */
.heaven-glow {
  position: absolute;
  inset: 0;
  pointer-events: none;
  background: radial-gradient(
    ellipse 60% 40% at 50% 50%,
    rgba(255, 255, 255, 0.04),
    transparent
  );
  animation: heavenPulse 4s ease-in-out infinite;
}

@keyframes heavenPulse {
  0%,
  100% {
    opacity: 0.5;
    transform: scale(1);
  }

  50% {
    opacity: 1;
    transform: scale(1.05);
  }
}

.heaven-roses {
  position: absolute;
  inset: 0;
  pointer-events: none;
  overflow: hidden;
}

.heaven-rose {
  position: absolute;
  color: rgba(255, 255, 255, 0.1);
  font-size: 1.2rem;
  animation: heavenFloat linear infinite;
}

@keyframes heavenFloat {
  from {
    transform: translateY(100vh) rotate(0deg);
    opacity: 0;
  }

  10% {
    opacity: 1;
  }

  90% {
    opacity: 1;
  }

  to {
    transform: translateY(-100px) rotate(360deg);
    opacity: 0;
  }
}

.tunnel-echo {
  position: absolute;
  inset: 0;
  pointer-events: none;
  background: radial-gradient(
    ellipse 30% 80% at 50% 50%,
    rgba(30, 20, 80, 0.8),
    rgba(10, 5, 30, 0.95)
  );
}

/* ========================================
   SECTION TRANSITIONS
   ======================================== */
.world-divider {
  height: 120px;
  position: relative;
  display: flex;
  align-items: center;
  justify-content: center;
  overflow: hidden;
}

.world-divider::before {
  content: "";
  position: absolute;
  inset: 0;
  background: linear-gradient(
    to bottom,
    transparent,
    rgba(255, 180, 100, 0.03),
    transparent
  );
}

.divider-line {
  width: 1px;
  height: 60px;
  background: linear-gradient(
    to bottom,
    transparent,
    rgba(255, 200, 150, 0.3),
    transparent
  );
}

/* ========================================
   LUST FOR LIFE SECTION
   ======================================== */
.lfl-carnival {
  position: absolute;
  inset: 0;
  pointer-events: none;
  overflow: hidden;
}

.carnival-light {
  position: absolute;
  border-radius: 50%;
  animation: carnivalGlow 2s ease-in-out infinite;
}

@keyframes carnivalGlow {
  0%,
  100% {
    opacity: 0.3;
    transform: scale(1);
  }

  50% {
    opacity: 0.7;
    transform: scale(1.2);
  }
}

/* ========================================
   CHEMTRAILS SECTION
   ======================================== */
.chemtrails-sky {
  position: absolute;
  inset: 0;
  pointer-events: none;
  background: linear-gradient(
    to bottom,
    rgba(80, 120, 160, 0.1),
    rgba(40, 80, 120, 0.05),
    transparent
  );
}

.chemtrail-line {
  position: absolute;
  height: 1px;
  opacity: 0.15;
  background: linear-gradient(
    to right,
    transparent,
    rgba(200, 220, 255, 0.8),
    transparent
  );
  transform-origin: left center;
  animation: chemtrailFade 8s ease-out infinite;
}

@keyframes chemtrailFade {
  from {
    width: 0;
    opacity: 0.2;
  }

  50% {
    width: 60%;
    opacity: 0.15;
  }

  to {
    width: 80%;
    opacity: 0;
  }
}

/* ========================================
   SCROLLBAR
   ======================================== */
::-webkit-scrollbar {
  width: 3px;
}

::-webkit-scrollbar-track {
  background: #050310;
}

::-webkit-scrollbar-thumb {
  background: linear-gradient(var(--neon-pink), var(--neon-amber));
  border-radius: 2px;
}

/* ========================================
   ALBUM SECTION LABELS
   ======================================== */
.section-era-badge {
  display: inline-block;
  padding: 4px 16px;
  border: 1px solid rgba(255, 200, 150, 0.2);
  font-family: "Inter", sans-serif;
  font-weight: 100;
  font-size: 0.55rem;
  letter-spacing: 0.5em;
  text-transform: uppercase;
  color: rgba(255, 200, 150, 0.4);
  margin-bottom: 20px;
  position: relative;
  z-index: 2;
  backdrop-filter: blur(4px);
}

/* ========================================
   EMOTIONAL MEMORY SCRATCHES
   ======================================== */
.vinyl-scratch {
  position: absolute;
  border-radius: 50%;
  border: 0.5px solid rgba(255, 255, 255, 0.1);
  pointer-events: none;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%);
}

.vinyl-fingerprint {
  position: absolute;
  inset: 0;
  border-radius: 50%;
  background: radial-gradient(
    circle at 60% 40%,
    rgba(255, 255, 255, 0.05),
    transparent
  );
  pointer-events: none;
}

/* ========================================
   NOTES PANEL
   ======================================== */
.notes-panel-toggle {
  position: fixed;
  top: 50%;
  left: 0;
  z-index: 510;
  transform: translateY(-50%);
  writing-mode: vertical-rl;
  text-orientation: mixed;
  font-family: "Inter", sans-serif;
  font-weight: 100;
  font-size: 0.55rem;
  letter-spacing: 0.3em;
  text-transform: uppercase;
  color: rgba(255, 200, 150, 0.3);
  cursor: none;
  padding: 16px 8px;
  border-right: 1px solid rgba(255, 200, 150, 0.1);
  transition: color 0.3s ease;
}

.notes-panel-toggle:hover {
  color: rgba(255, 200, 150, 0.7);
}

/* ========================================
   RESPONSIVE
   ======================================== */
@media (max-width: 768px) {
  /* Cursor — hide on touch devices */
  .cursor {
    display: none;
  }

  body {
    cursor: auto;
  }

  /* Header */
  .world-header {
    padding: 12px 16px;
  }

  .header-logo {
    font-size: 0.9rem;
  }

  .header-nav {
    display: none;
  }

  /* Now playing — full-width bottom bar */
  .now-playing {
    bottom: 0;
    right: 0;
    left: 0;
    width: 100%;
    border-radius: 0;
    padding: 10px 16px;
  }

  .np-controls {
    justify-content: center;
  }

  /* World sections */
  .world-section {
    padding: 80px 16px 120px;
  }

  /* Vinyl grid — 2 columns */
  .vinyl-grid {
    display: grid;
    grid-template-columns: repeat(2, 1fr);
    gap: 20px;
    padding: 0 10px;
  }

  .vinyl-card {
    align-items: center;
  }

  /* Player overlay */
  .player-inner {
    flex-direction: column;
    padding: 20px;
    overflow-y: auto;
    max-height: 90vh;
  }

  .player-vinyl-large {
    width: 180px;
    height: 180px;
    margin: 0 auto;
  }

  .player-song {
    font-size: 1.5rem;
    text-align: center;
  }

  .player-album {
    text-align: center;
  }

  .player-controls {
    justify-content: center;
  }
}

/* ========================================
   MOOD OVERLAY — global (not inside media query)
   Works at any viewport width, can't get stuck
   ======================================== */
#mood-overlay {
  position: fixed;
  inset: 0;
  z-index: 900;
  background: rgba(5, 3, 15, 0.96);
  backdrop-filter: blur(20px);
  display: none;
  /* hidden by default everywhere */
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 16px;
  padding: 40px 24px;
}

#mood-overlay.open {
  display: flex;
  /* toggled by toggleMoodOverlay() */
}

#mood-overlay .mood-label {
  font-size: 0.7rem;
  letter-spacing: 0.4em;
  color: rgba(255, 200, 150, 0.5);
  margin-bottom: 8px;
}

#mood-overlay .mood-tag {
  font-size: 0.9rem;
  padding: 10px 28px;
  width: 100%;
  text-align: center;
  max-width: 260px;
}

#mood-overlay-close {
  position: absolute;
  top: 20px;
  right: 24px;
  background: none;
  border: none;
  color: rgba(255, 200, 150, 0.5);
  font-size: 1.4rem;
  cursor: pointer;
}

/* ☽ header button — only visible on mobile via the responsive block */
.mood-btn-mobile {
  display: none;
  /* hidden on desktop */
  background: none;
  border: none;
  cursor: pointer;
  color: rgba(255, 200, 150, 0.6);
  font-size: 1.1rem;
  padding: 4px 8px;
  pointer-events: all;
}

@media (max-width: 768px) {
