/* =====================================================================
   PARADISE.EXE / THE DREAM ARCHIVE
   Presentation layer. Existing IDs, state classes and engine are retained.
   ===================================================================== */
:root {
  --paper: #eee7d9;
  --ink: #171819;
  --muted: #bbb4a7;
  --rule: #ffffff29;
  --scene: #161a1c;
  --scene-light: #303b3d;
  --scene-accent: #c5b291;
  --serif: "Cormorant Garamond", Georgia, serif;
  --display: "Playfair Display", Georgia, serif;
  --sans: "Inter", Arial, sans-serif;
  --gutter: clamp(24px, 4.5vw, 80px);
}
body {
  background: var(--scene);
  color: var(--paper);
  font-weight: 400;
  cursor: auto;
}
button,
.as-card,
.vinyl-card {
  cursor: pointer;
}
button,
textarea {
  font: inherit;
}
button:focus-visible,
[tabindex]:focus-visible,
textarea:focus-visible {
  outline: 2px solid var(--scene-accent);
  outline-offset: 5px;
}
::selection {
  background: #b5a383;
  color: #141719;
}
.cursor {
  width: 24px;
  height: 24px;
  border-color: #eee7d963;
  opacity: 0.45;
}
.cursor.hovering {
  border-color: var(--paper);
}
.grain {
  inset: 0;
  width: 100%;
  height: 100%;
  animation: none;
  opacity: 0.025;
  will-change: auto;
}
.particles-canvas {
  opacity: 0.12;
}
.ambient-viz {
  opacity: 0.1;
  height: 30px;
}
.vhs-overlay,
.vhs-glitch,
.chroma-r,
.chroma-b,
.clouds-layer,
.highway-scene,
.as-light-leak,
.btd-roses,
.btd-flag,
.palm-tree,
.lfl-carnival,
.heaven-roses,
.puddle,
.pool-shimmer,
.nfr-ocean,
.tunnel-echo,
.heaven-glow,
.chemtrails-sky,
.chemtrail-line {
  display: none !important;
}
/* Decorative engine targets remain in the DOM for existing transitions. */
#intro-scene {
  align-items: stretch;
  justify-content: flex-end;
  padding: 12vh var(--gutter);
  background: #13191b;
  cursor: auto;
}
.intro-sky {
  background: linear-gradient(105deg, #13191b 15%, #192326 100%);
}
.stars-layer {
  opacity: 0.18;
}
.light-shaft {
  opacity: 0.2;
}
.intro-masthead {
  position: absolute;
  z-index: 3;
  top: 32px;
  left: var(--gutter);
  right: var(--gutter);
  display: flex;
  justify-content: space-between;
  gap: 20px;
  font: 400 12px/1.5 var(--sans);
  letter-spacing: 0.19em;
  border-bottom: 1px solid #eee7d934;
  padding-bottom: 20px;
  color: #dbd7cd;
}
.intro-frame {
  position: absolute;
  inset: 14% 7% 14% 43%;
  background-image:
    linear-gradient(0deg, #0c141540, #0c141510), var(--archive-image);
  background-size: cover, 290%;
  background-position:
    center,
    39% 93%;
  filter: grayscale(1) sepia(0.12);
  opacity: 0.8;
  box-shadow:
    0 0 0 12px #e7e0d208,
    0 0 0 13px #e7e0d22b;
}
.intro-content {
  top: auto;
  text-align: left;
  width: 100%;
  max-width: 1200px;
}
.intro-title {
  font-family: var(--display);
  font-size: clamp(4rem, 11vw, 11rem);
  font-weight: 400;
  font-style: normal;
  letter-spacing: -0.07em;
  line-height: 1.12;
  color: var(--paper);
  background: none;
  text-shadow: 0 3px 35px #0004;
  animation: titleReveal 1.8s ease both 0.5s;
  width: fit-content;
}
.intro-exe {
  display: block;
  font: italic 400 0.39em/1.1 var(--serif);
  letter-spacing: -0.04em;
  padding-left: 0.07em;
}
.intro-sub {
  font: 400 12px/1.6 var(--sans);
  letter-spacing: 0.24em;
  color: #d2cbbd;
  margin-top: 26px;
  animation: fadeUp 1.2s ease both 1s;
}
.enter-btn {
  min-width: 220px;
  min-height: 54px;
  margin-top: 36px;
  padding: 16px 0;
  display: inline-flex;
  justify-content: space-between;
  gap: 50px;
  background: transparent;
  border: 0;
  border-bottom: 1px solid #eee7d99c;
  border-radius: 0;
  color: var(--paper);
  font: 400 14px/1.5 var(--sans);
  letter-spacing: 0.07em;
  text-transform: none;
  backdrop-filter: none;
  box-shadow: none;
  animation: fadeUp 1.2s ease both 1.4s;
  cursor: pointer;
  transition:
    color 0.3s,
    border-color 0.3s;
}
.enter-btn::before {
  content: none;
}
.enter-btn:hover {
  background: transparent;
  color: #fff;
  border-color: #fff;
}
.enter-btn span {
  font-size: 21px;
  transition: transform 0.35s;
}
.enter-btn:hover span {
  transform: translate(3px, -3px);
}
.intro-caption {
  position: absolute;
  bottom: 5%;
  right: 7%;
  font: italic 22px/1.25 var(--serif);
  color: #cbc6ba;
  text-align: right;
}
/* The archive: fixed editorial spine + scrollable photographic chapter index. */
#album-select-screen {
  background: #171b1c;
  align-items: stretch;
  padding-top: 85px;
}
#album-select-screen.visible {
  display: grid;
  grid-template-columns: 32% minmax(0, 1fr);
}
#album-select-screen::after {
  content: none;
}
.as-bg {
  background: none;
}
.as-bg::after {
  content: none;
}
.as-film-grain {
  opacity: 0.018;
}
.as-header {
  position: absolute;
  inset: 0 0 auto;
  width: 100%;
  height: 85px;
  padding: 24px var(--gutter);
  align-items: center;
  gap: 20px;
  border-color: var(--rule);
  z-index: 170;
}
.as-logo,
.header-logo {
  font: italic 400 24px/1.2 var(--serif);
  color: var(--paper);
  letter-spacing: -0.025em;
}
.as-tagline {
  color: #c0bbae;
  font: 400 12px/1.5 var(--sans);
  letter-spacing: 0.16em;
}
.archive-heading {
  position: relative;
  z-index: 155;
  padding: 65px 24px 40px var(--gutter);
  display: flex;
  flex-direction: column;
  align-items: flex-start;
}
.archive-kicker {
  color: #bcb2a1;
  font: 400 12px/1.6 var(--sans);
  letter-spacing: 0.15em;
}
.archive-heading h1 {
  margin: 42px 0 24px;
  font: 400 clamp(36px, 4vw, 68px)/1.08 var(--display);
  letter-spacing: -0.055em;
}
.archive-heading h1 em {
  font-family: var(--serif);
  font-weight: 400;
}
.archive-heading p {
  color: #bbb6aa;
  font: 400 15px/1.8 var(--sans);
}
.archive-signature {
  margin-top: auto;
  padding-top: 40px;
  color: #bbb6aa;
  font: italic 28px/1.3 var(--serif);
}
.as-grid {
  width: 100%;
  max-width: none;
  max-height: none;
  height: 100%;
  margin: 0;
  padding: 34px var(--gutter) 64px 18px;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  grid-template-rows: none;
  grid-auto-rows: auto;
  gap: 30px 24px;
  align-content: start;
  overflow-y: auto;
  scrollbar-width: thin;
  scrollbar-color: #817866 #171b1c;
  counter-reset: era;
  scroll-behavior: smooth;
}
.as-grid::-webkit-scrollbar {
  display: block;
  width: 4px;
}
.as-card {
  --frame-pos: 0% 0%;
  --frame-size: 300%;
  --frame-filter: saturate(0.5);
  position: relative;
  isolation: isolate;
  min-height: 290px;
  aspect-ratio: auto;
  padding: 145px 20px 24px;
  border: none;
  border-bottom: 1px solid var(--rule);
  align-items: stretch;
  justify-content: flex-end;
  background: transparent;
  backdrop-filter: none;
  -webkit-backdrop-filter: none;
  contain: none;
  counter-increment: era;
  transition: border-color 0.4s;
  overflow: hidden;
}
.as-card::before {
  content: "";
  position: absolute;
  z-index: -2;
  inset: 0 0 100px;
  background-image: var(--archive-image);
  background-size: var(--frame-size);
  background-position: var(--frame-pos);
  filter: var(--frame-filter);
  opacity: 0.62;
  transition:
    opacity 0.6s,
    transform 0.8s cubic-bezier(0.2, 0.7, 0.3, 1);
}
.as-card::after {
  content: counter(era, decimal-leading-zero);
  position: absolute;
  left: 0;
  top: 12px;
  padding: 8px 13px;
  background: #151a1bd9;
  color: var(--paper);
  font: 400 12px/1 var(--sans);
  letter-spacing: 0.12em;
}
.as-card:hover,
.as-card:active {
  transform: none;
  background: transparent;
  border-color: #d5c7ac;
}
.as-card:hover::before,
.as-card:focus-visible::before {
  opacity: 0.9;
  transform: scale(1.035);
}
.as-card-info {
  text-align: left;
  align-items: flex-start;
  display: grid;
  grid-template-columns: 1fr auto;
  gap: 8px 12px;
}
.as-card-title {
  grid-column: 1/-1;
  color: var(--paper);
  height: auto;
  font: 400 clamp(22px, 2.1vw, 34px)/1.12 var(--serif);
  letter-spacing: -0.02em;
  margin: 0;
}
.as-card:hover .as-card-title {
  color: var(--paper);
}
.as-card-year,
.as-card-tracks {
  margin: 0;
  color: #bcb7ab;
  font: 400 12px/1.5 var(--sans);
  letter-spacing: 0.08em;
}
.as-card:nth-child(1) {
  --frame-pos: 47% 7%;
  --frame-size: 290%;
}
.as-card:nth-child(2) {
  --frame-pos: 66% 35%;
  --frame-size: 460%;
  --frame-filter: sepia(0.4) saturate(0.65);
}
.as-card:nth-child(3) {
  --frame-pos: 39% 95%;
  --frame-size: 280%;
  --frame-filter: grayscale(1);
}
.as-card:nth-child(4) {
  --frame-pos: 100% 5%;
  --frame-size: 290%;
  --frame-filter: sepia(0.12) saturate(0.6);
}
.as-card:nth-child(5) {
  --frame-pos: 71% 100%;
  --frame-size: 380%;
  --frame-filter: sepia(0.18) saturate(0.65);
}
.as-card:nth-child(6) {
  --frame-pos: 0% 0%;
  --frame-size: 290%;
  --frame-filter: saturate(0.5);
}
.as-card:nth-child(7) {
  --frame-pos: 0% 100%;
  --frame-size: 310%;
  --frame-filter: sepia(0.25) saturate(0.2);
}
/* Ocean Blvd and Specials use abstract crops of the existing archive photograph,
   not substitute album covers. */
.as-card:nth-child(8) {
  --frame-pos: 38% 67%;
  --frame-size: 650%;
  --frame-filter: grayscale(1) brightness(0.6);
}
.as-card:nth-child(9) {
  grid-column: 1/-1;
  min-height: 210px;
  --frame-pos: 44% 0%;
  --frame-size: 140%;
  --frame-filter: grayscale(0.7) sepia(0.2);
}
#as-scroll-thumb {
  background: #c5b291 !important;
}
/* Era palettes follow the section visibility already managed by the engine. */
body:has(#btd:not([style*="display: none"])) {
  --scene: #1c3044;
  --scene-light: #405b72;
  --scene-accent: #bfd7e8;
  --scene-detail: #bfd7e8;
}
body:has(#paradise-ep:not([style*="display: none"])) {
  --scene: #42371f;
  --scene-light: #766338;
  --scene-accent: #e4ca83;
  --scene-detail: #e4ca83;
}
body:has(#uv:not([style*="display: none"])) {
  --scene: #151515;
  --scene-light: #343434;
  --scene-accent: #d2d2d2;
  --scene-detail: #d2d2d2;
}
body:has(#honey:not([style*="display: none"])) {
  --scene: #202f40;
  --scene-light: #62383f;
  --scene-accent: #bdccd9;
  --scene-detail: #bdccd9;
}
body:has(#lfl:not([style*="display: none"])) {
  --scene: #193b39;
  --scene-light: #36635e;
  --scene-accent: #aed8cb;
  --scene-detail: #aed8cb;
}
body:has(#nfr:not([style*="display: none"])) {
  --scene: #464029;
  --scene-light: #57634c;
  --scene-accent: #e0c981;
  --scene-detail: #d59a89;
}
body:has(#chemtrails:not([style*="display: none"])) {
  --scene: #343331;
  --scene-light: #575551;
  --scene-accent: #d3cec4;
  --scene-detail: #d3cec4;
}
body:has(#tunnel:not([style*="display: none"])) {
  --scene: #30302e;
  --scene-light: #50504a;
  --scene-accent: #d5bf7f;
  --scene-detail: #d5bf7f;
}
body:has(#heaven:not([style*="display: none"])) {
  --scene: #2e3527;
  --scene-light: #505940;
  --scene-accent: #d4bf87;
  --scene-detail: #d4bf87;
}
#main-world {
  background: var(--scene);
}
.world-header {
  padding: 20px var(--gutter);
  min-height: 80px;
  background: var(--scene);
  border-color: var(--rule);
  backdrop-filter: none;
}
.header-time {
  color: var(--muted);
  font: 400 12px/1.4 var(--sans);
}
.world-back-btn {
  position: static;
  padding: 10px 14px;
  min-height: 44px;
  border: 1px solid var(--rule);
  border-radius: 0;
  color: var(--paper);
  font: 400 13px/1.4 var(--sans);
  letter-spacing: 0.05em;
  backdrop-filter: none;
  cursor: pointer;
}
.world-back-btn:hover {
  background: #ffffff0b;
  color: #fff;
}
.world-section,
#paradise-ep,
#chemtrails {
  background: var(--scene) !important;
  min-height: 100vh !important;
  display: grid;
  grid-template-columns: minmax(0, 0.85fr) minmax(0, 1.5fr);
  grid-template-rows: auto auto auto 1fr;
  align-items: start;
  align-content: start;
  padding: 160px var(--gutter) calc(190px + env(safe-area-inset-bottom));
  gap: 22px 6vw;
  overflow: clip;
  contain: none;
}
.world-section::before {
  content: "";
  position: absolute;
  inset: 100px 63% 130px 0;
  pointer-events: none;
  background: linear-gradient(180deg, var(--scene-light), transparent);
  opacity: 0.6;
}
.section-atmosphere {
  opacity: 0.14;
}
.section-era-badge {
  grid-column: 1;
  padding: 0;
  margin: 0;
  border: 0;
  color: var(--scene-accent);
  font: 400 12px/1.7 var(--sans);
  letter-spacing: 0.14em;
  backdrop-filter: none;
  max-width: 100%;
}
.world-section .world-title {
  grid-column: 1;
  margin: 0;
  color: var(--paper) !important;
  text-shadow: none !important;
  font: 400 clamp(40px, 5.7vw, 90px)/1.03 var(--display) !important;
  text-align: left;
  letter-spacing: -0.05em;
  overflow-wrap: anywhere;
}
.world-subtitle {
  display: block;
  grid-column: 1;
  margin: 10px 0 35px;
  color: #c0b9ad;
  opacity: 1;
  text-align: left;
  text-transform: none;
  font: italic 21px/1.4 var(--serif);
  letter-spacing: 0;
  max-width: 290px;
}
.vinyl-grid {
  grid-column: 2;
  grid-row: 1/5;
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 0 24px;
  padding: 0;
  animation: none;
  counter-reset: track;
}
.vinyl-card {
  position: relative;
  flex-direction: row;
  align-items: center;
  gap: 16px;
  padding: 24px 0;
  min-width: 0;
  border-top: 1px solid var(--rule);
  contain: none;
  counter-increment: track;
  transition: background 0.4s;
}
.vinyl-card:hover {
  transform: none;
  box-shadow: none;
  background: #ffffff06;
}
.vinyl-wrapper,
.vinyl-disc {
  width: 86px;
  height: 86px;
  flex-shrink: 0;
}
.vinyl-wrapper {
  filter: drop-shadow(0 8px 10px #0006);
}
.vinyl-disc,
.vinyl-disc.dragging,
.player-vinyl-large {
  cursor: grab;
}
.vinyl-disc.dragging,
.player-vinyl-large:active {
  cursor: grabbing;
}
.vinyl-info {
  min-width: 0;
  width: auto;
  text-align: left;
  flex: 1;
}
.vinyl-info::before {
  content: counter(track, decimal-leading-zero);
  display: block;
  margin-bottom: 7px;
  color: var(--scene-accent);
  font: 400 12px/1 var(--sans);
}
.vinyl-song-name {
  font: 400 20px/1.2 var(--serif);
  color: var(--paper);
  overflow-wrap: anywhere;
}
.vinyl-play-count {
  font: 400 12px/1.5 var(--sans);
  color: #bab4a9;
  letter-spacing: 0.02em;
  margin-top: 8px;
}
.drag-hint {
  top: -18px;
  color: var(--scene-accent);
  font: 400 12px/1 var(--sans);
  letter-spacing: 0;
}
/* Composition shifts: road / noir / Riviera / coast / intimate final chapters. */
#paradise-ep {
  grid-template-columns: 1fr;
  padding-top: 145px;
  gap: 24px;
}
#paradise-ep .world-title {
  font-style: italic !important;
  font-size: clamp(64px, 9vw, 136px) !important;
}
#paradise-ep .world-subtitle {
  max-width: none;
}
#paradise-ep .vinyl-grid {
  grid-column: 1;
  grid-row: auto;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 0 40px;
}
#uv {
  grid-template-columns: minmax(0, 1fr);
  padding-left: max(var(--gutter), 12vw);
  padding-right: max(var(--gutter), 12vw);
}
#uv .world-title {
  text-transform: uppercase;
  font-size: clamp(32px, 6.5vw, 100px) !important;
  letter-spacing: -0.06em;
}
#uv .vinyl-grid {
  grid-column: 1;
  grid-row: auto;
  gap: 0 64px;
}
#uv .section-atmosphere {
  opacity: 0.22;
}
#honey {
  grid-template-columns: minmax(0, 1.5fr) minmax(0, 1fr);
}
#honey .section-era-badge,
#honey .world-title,
#honey .world-subtitle {
  grid-column: 2;
  text-align: right;
}
#honey .world-title {
  font-family: var(--serif) !important;
  font-style: italic !important;
}
#honey .vinyl-grid {
  grid-column: 1;
}
#honey .world-subtitle {
  margin-left: auto;
}
#lfl .world-title {
  font-family: var(--serif) !important;
  font-size: clamp(64px, 7.5vw, 120px) !important;
}
#nfr .world-title {
  font-family: var(--serif) !important;
  font-style: italic !important;
}
#chemtrails {
  gap: 34px 9vw;
  padding-top: 190px;
}
#chemtrails .world-title {
  font-family: var(--serif) !important;
}
#chemtrails .section-atmosphere {
  opacity: 0.06;
}
#tunnel {
  grid-template-columns: minmax(0, 0.8fr) minmax(0, 1.2fr);
  padding-left: 10vw;
  padding-right: 10vw;
}
#tunnel .vinyl-grid {
  grid-template-columns: 1fr;
}
#tunnel .world-title {
  font-style: italic !important;
}
#heaven {
  text-align: center;
  grid-template-columns: 1fr;
  padding-top: 150px;
}
#heaven .world-title,
#heaven .world-subtitle {
  text-align: center;
  max-width: none;
}
#heaven .world-title {
  font: italic 400 clamp(50px, 7vw, 112px)/1.05 var(--serif) !important;
}
#heaven .vinyl-grid {
  grid-column: 1;
  grid-row: auto;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 0 32px;
}
#heaven .secret-badge {
  position: static;
  grid-column: 1;
  justify-self: center;
  font-size: 12px;
}
/* Persistent player: an unobtrusive full-width transport rail. */
.now-playing {
  bottom: 0;
  left: 0;
  right: 0;
  width: 100%;
  padding: 14px var(--gutter) calc(14px + env(safe-area-inset-bottom));
  display: grid;
  grid-template-columns: 140px 40px minmax(0, 1fr) auto;
  gap: 20px;
  align-items: center;
  border: 0;
  border-top: 1px solid var(--rule);
  border-radius: 0;
  background: var(--scene);
}
.now-playing::before {
  content: none;
}
.np-label {
  margin: 0;
  color: #bcb6aa;
  font: 400 12px/1.5 var(--sans);
  letter-spacing: 0.12em;
}
.now-playing > div[style] {
  margin-top: 0 !important;
  min-width: 0;
}
.np-title {
  max-width: none;
  font: 400 22px/1.2 var(--serif);
  color: var(--paper);
}
.np-album {
  font: 400 12px/1.4 var(--sans);
  color: #c0b9ad;
  letter-spacing: 0.03em;
  overflow-wrap: anywhere;
}
.np-progress {
  position: absolute;
  margin: 0;
  top: 0;
  left: 0;
  right: 0;
  height: 2px;
}
.np-progress-bar {
  background: var(--scene-accent);
  box-shadow: none;
}
.np-controls {
  margin: 0;
  gap: 12px;
}
.np-btn {
  min-width: 44px;
  min-height: 44px;
  color: var(--paper);
  cursor: pointer;
  font-size: 18px;
}
.np-btn:hover {
  transform: none;
  color: #fff;
  background: #ffffff0b;
}
/* Listening room */
#vinyl-player {
  background: #111516ed;
  backdrop-filter: none;
  -webkit-backdrop-filter: none;
  overflow-y: auto;
  padding: 80px 0 40px;
  align-items: safe center;
}
.player-inner {
  width: min(1120px, 90%);
  max-width: 1120px;
  min-height: 520px;
  padding: clamp(24px, 5vw, 72px);
  gap: clamp(30px, 6vw, 90px);
  background: var(--scene);
  border: 1px solid var(--rule);
  position: relative;
}
.player-vinyl-large {
  width: clamp(220px, 30vw, 380px);
  height: auto;
  aspect-ratio: 1;
  filter: drop-shadow(0 22px 20px #0006);
}
.player-vinyl-canvas {
  display: block;
  touch-action: none;
}
.listening-label {
  color: var(--scene-accent);
  font: 400 12px/1.6 var(--sans);
  letter-spacing: 0.16em;
  margin-bottom: 24px;
}
.player-song {
  color: var(--paper);
  font: 400 clamp(28px, 3.4vw, 48px)/1.1 var(--serif);
  letter-spacing: -0.02em;
  overflow-wrap: anywhere;
}
.player-album {
  color: #beb7aa;
  font: 400 12px/1.6 var(--sans);
  letter-spacing: 0.09em;
  margin: 14px 0 30px;
}
.player-progress-wrap {
  cursor: default;
  background: #ffffff2b;
}
.player-progress-fill {
  background: var(--scene-accent);
}
.player-progress-dot {
  width: 6px;
  height: 6px;
  background: var(--paper);
  box-shadow: none;
}
.player-time {
  font: 400 12px/1.5 var(--sans);
  color: #c5bdaf;
  letter-spacing: 0;
  margin-bottom: 24px;
}
.player-controls {
  gap: 16px;
  margin-bottom: 20px;
}
.player-btn {
  min-width: 44px;
  min-height: 44px;
  color: var(--paper);
  cursor: pointer;
}
.player-btn:hover {
  transform: none;
  color: #fff;
}
.player-btn.play-btn {
  background: var(--paper);
  color: var(--scene);
  width: 56px;
  height: 56px;
  box-shadow: none;
  border: 0;
}
.player-btn.play-btn:hover {
  background: #fff;
  box-shadow: none;
}
#fav-btn {
  font-size: 24px !important;
}
.player-close {
  position: fixed;
  top: 20px;
  right: var(--gutter);
  width: 44px;
  height: 44px;
  color: #e7dfd0;
  border: 1px solid #ffffff38;
  cursor: pointer;
  z-index: 2;
  background: #151819;
}
.player-close:hover {
  transform: none;
  background: #2c3031;
}
.player-scrub-hint {
  font: 400 12px/1.5 var(--sans);
  text-transform: none;
  color: #c0b9ac;
  letter-spacing: 0.02em;
}
.memory-label {
  display: block;
  color: var(--scene-accent);
  font: italic 20px/1.4 var(--serif);
  margin-bottom: 8px;
}
.player-note {
  background: #0000000a;
  border: 0;
  border-bottom: 1px solid #ffffff40;
  border-radius: 0;
  padding: 10px 0;
  color: var(--paper);
  font: italic 20px/1.4 var(--serif);
  min-height: 76px;
}
.player-note::placeholder {
  color: #bdb5a7;
}
.player-note:focus {
  border-color: var(--scene-accent);
}
#cinematic-overlay {
  background: #121617;
}
#cinematic-overlay > div {
  filter: saturate(0.25);
}
#loading-veil {
  background: #141a1c;
}
.loading-text {
  color: #dad2c3;
  font: italic 32px/1.2 var(--serif);
  letter-spacing: -0.02em;
}
.loading-bar {
  width: 180px;
}
.loading-fill {
  background: #c5b291;
  box-shadow: none;
}
/* Recomposition, not scale-down. No rigid card rows or truncated song names. */
@media (min-width: 1600px) {
  .as-card {
    min-height: 350px;
    padding-top: 205px;
  }
  .world-section {
    gap: 28px 8vw;
  }
  .vinyl-wrapper,
  .vinyl-disc {
    width: 112px;
    height: 112px;
  }
}
@media (max-width: 1100px) {
  #album-select-screen.visible {
    grid-template-columns: 29% minmax(0, 1fr);
  }
  .archive-heading {
    padding-top: 45px;
  }
  .archive-heading h1 {
    font-size: 38px;
  }
  .as-card {
    padding-left: 0;
    padding-right: 0;
    min-height: 270px;
  }
  .world-section,
  #honey,
  #tunnel,
  #chemtrails {
    grid-template-columns: 1fr;
    padding: 125px var(--gutter) 180px;
    gap: 20px;
  }
  .world-section .world-title {
    font-size: clamp(44px, 7vw, 76px) !important;
  }
  .world-section .section-era-badge,
  .world-section .world-title,
  .world-section .world-subtitle {
    grid-column: 1;
    text-align: left;
    margin-left: 0;
  }
  .world-section .world-subtitle {
    max-width: none;
    margin-bottom: 24px;
  }
  .world-section .vinyl-grid {
    grid-column: 1;
    grid-row: auto;
    grid-template-columns: repeat(2, minmax(0, 1fr));
    gap: 0 36px;
  }
  .world-section::before {
    inset: 80px 20% 60% 0;
  }
  #heaven .world-title,
  #heaven .world-subtitle {
    text-align: center;
  }
  .now-playing {
    grid-template-columns: 32px minmax(0, 1fr) auto;
    gap: 16px;
  }
  .np-label {
    display: none;
  }
}
@media (max-width: 700px) {
  :root {
    --gutter: 24px;
  }
  .cursor {
    display: none;
  }
  #intro-scene {
    padding: 0 24px 18vh;
    min-height: 100svh;
  }
  .intro-masthead {
    top: 24px;
    font-size: 12px;
  }
  .intro-masthead span:last-child {
    max-width: 140px;
    text-align: right;
    letter-spacing: 0.08em;
  }
  .intro-frame {
    inset: 17% 9% 33% 23%;
    background-size: cover, 310%;
    opacity: 0.58;
  }
  .intro-title {
    font-size: clamp(60px, 16vw, 110px);
    letter-spacing: -0.06em;
  }
  .intro-sub {
    max-width: 240px;
    font-size: 12px;
    letter-spacing: 0.16em;
  }
  .intro-caption {
    bottom: 5%;
    font-size: 20px;
  }
  .enter-btn {
    margin-top: 28px;
  }
  #album-select-screen {
    padding-top: 190px;
  }
  #album-select-screen.visible {
    display: flex;
  }
  .as-header {
    height: 68px;
    padding: 18px 24px;
    flex-direction: row;
  }
  .as-logo {
    font-size: 22px;
  }
  .as-tagline {
    max-width: 130px;
    text-align: right;
    font-size: 12px;
    letter-spacing: 0.04em;
  }
  .archive-heading {
    position: absolute;
    top: 68px;
    left: 0;
    right: 0;
    height: 122px;
    padding: 22px 24px;
    display: block;
  }
  .archive-heading h1 {
    margin: 8px 0 0;
    font-size: 29px;
    line-height: 1.1;
  }
  .archive-heading h1 br {
    display: none;
  }
  .archive-heading h1 em {
    margin-left: 6px;
  }
  .archive-heading p,
  .archive-signature {
    display: none;
  }
  .archive-kicker {
    font-size: 12px;
  }
  .as-grid {
    width: 100%;
    max-height: none;
    padding: 8px 24px calc(40px + env(safe-area-inset-bottom));
    gap: 22px 18px;
    flex: 1;
    grid-template-columns: repeat(2, minmax(0, 1fr));
    grid-template-rows: none;
    grid-auto-rows: auto;
  }
  .as-card {
    padding: 122px 0 20px;
    min-height: 248px;
  }
  .as-card::before {
    bottom: 116px;
  }
  .as-card-title {
    font-size: 24px;
  }
  .as-card-info {
    gap: 8px;
  }
  .as-card-year,
  .as-card-tracks {
    font-size: 12px;
    letter-spacing: 0;
  }
  .as-card:nth-child(9) {
    min-height: 230px;
  }
  .world-header {
    min-height: 76px;
    padding: 14px 20px;
  }
  .world-header > div {
    gap: 12px !important;
  }
  .header-logo {
    font-size: 22px;
  }
  .header-time {
    font-size: 12px;
    letter-spacing: 0;
  }
  .world-back-btn {
    position: static;
    font-size: 12px;
    padding: 10px;
  }
  .world-section,
  #paradise-ep,
  #uv,
  #honey,
  #lfl,
  #nfr,
  #chemtrails,
  #tunnel,
  #heaven {
    padding: 116px 24px calc(185px + env(safe-area-inset-bottom));
    gap: 18px;
  }
  .world-section .world-title {
    font-size: clamp(38px, 11vw, 68px) !important;
  }
  #uv .world-title {
    font-size: clamp(30px, 8vw, 54px) !important;
  }
  .world-subtitle {
    font-size: 20px;
  }
  .world-section .vinyl-grid {
    grid-template-columns: 1fr;
    gap: 0;
  }
  .vinyl-card {
    padding: 20px 0;
    gap: 22px;
  }
  .vinyl-wrapper,
  .vinyl-disc {
    width: 86px;
    height: 86px;
  }
  .vinyl-song-name {
    font-size: 24px;
  }
  .vinyl-info::before {
    margin-bottom: 6px;
  }
  .vinyl-play-count {
    margin-top: 6px;
  }
  .now-playing {
    padding: 12px 18px calc(12px + env(safe-area-inset-bottom));
    grid-template-columns: minmax(0, 1fr) auto;
    gap: 8px;
  }
  .np-vinyl-mini {
    display: none;
  }
  .np-controls {
    gap: 0;
  }
  .np-title {
    font-size: 20px;
  }
  .np-album {
    font-size: 12px;
    max-height: 3em;
    overflow: hidden;
  }
  #vinyl-player {
    padding: 76px 0 24px;
    align-items: flex-start;
  }
  .player-inner {
    width: calc(100% - 32px);
    min-height: auto;
    flex-direction: column;
    padding: 26px 24px;
    gap: 30px;
    max-height: none;
    overflow: visible;
  }
  .player-vinyl-large {
    width: min(54vw, 240px);
    height: auto;
  }
  .player-info {
    width: 100%;
  }
  .listening-label {
    margin-bottom: 12px;
    text-align: center;
  }
  .player-song {
    text-align: center;
    font-size: 32px;
  }
  .player-album {
    margin: 12px 0 26px;
  }
  .player-controls {
    justify-content: center;
  }
  .player-close {
    top: 16px;
    right: 16px;
  }
}
@media (max-width: 370px) {
  .as-grid {
    grid-template-columns: 1fr;
  }
  .as-card {
    min-height: 250px;
  }
  .header-logo {
    font-size: 18px;
  }
  .header-time {
    display: none;
  }
  .intro-title {
    font-size: 58px;
  }
  .archive-heading h1 {
    font-size: 26px;
  }
}
@media (max-height: 550px) and (min-width: 701px) {
  #intro-scene {
    padding-bottom: 7vh;
  }
  .intro-title {
    font-size: 70px;
  }
  .intro-sub {
    margin-top: 10px;
  }
  .enter-btn {
    margin-top: 16px;
  }
  .archive-heading {
    padding-top: 20px;
  }
  .archive-heading h1 {
    margin-top: 18px;
  }
  .archive-signature {
    display: none;
  }
  #vinyl-player {
    align-items: flex-start;
  }
}
@media (prefers-reduced-motion: reduce) {
  html,
  .as-grid {
    scroll-behavior: auto;
  }
  *,
  *::before,
  *::after {
    animation-duration: 0.01ms !important;
    animation-delay: 0ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
  }
  .particles-canvas,
  .stars-layer,
  .ambient-viz,
  .section-atmosphere {
    visibility: hidden;
  }
  /* Let GSAP complete its original callbacks while suppressing visual travel. */
  .intro-title,
  .intro-sub,
  .as-header,
  .as-card,
  .world-title,
  .world-subtitle,
  .vinyl-card {
    transform: none !important;
    filter: none !important;
  }
}
/* Keep image apertures independent of long album titles. */
.as-card {
  padding-top: 174px;
}
.as-card::before {
  bottom: auto;
  height: 150px;
}
@media (min-width: 1600px) {
  .as-card {
    padding-top: 234px;
  }
  .as-card::before {
    height: 210px;
  }
}
@media (max-width: 700px) {
  .as-card {
    padding-top: 144px;
  }
  .as-card::before {
    height: 120px;
  }
}

/* Archive flow repair: decorations must not occupy collection layout cells. */
#album-select-screen {
  padding-top: 0;
  overflow-y: auto;
  overflow-x: hidden;
}
#album-select-screen.visible {
  display: block;
}
#as-particle-container {
  position: absolute;
  inset: 0;
  overflow: hidden;
  pointer-events: none;
}
#album-select-screen .as-header {
  position: relative;
  inset: auto;
}
#album-select-screen .archive-heading {
  position: relative;
  inset: auto;
  height: auto;
}
#album-select-screen .as-grid {
  position: relative;
  width: 100%;
  max-width: 1280px;
  height: auto;
  min-height: 0;
  max-height: none;
  margin: 0 auto;
  padding-left: var(--gutter);
  padding-right: var(--gutter);
  overflow: visible;
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  grid-template-rows: none;
  grid-auto-rows: auto;
}
#album-select-screen .as-card:nth-child(9) {
  grid-column: auto;
}
@media (max-width: 1100px) {
  #album-select-screen .as-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
}
@media (max-width: 700px) {
  #album-select-screen .as-grid {
    grid-template-columns: minmax(0, 1fr);
    flex: none;
  }
}

/* Shared album structure: Paradise is the reference; era palettes stay above. */
#main-world {
  height: 100dvh;
  min-height: 0;
  overflow-y: auto;
  overflow-x: hidden;
  overscroll-behavior-y: contain;
}
#main-world .world-section {
  grid-template-columns: minmax(0, 1fr);
  grid-template-rows: auto auto auto 1fr;
  height: auto;
  max-height: none;
  padding: 145px var(--gutter) max(calc(190px + env(safe-area-inset-bottom)), calc(var(--transport-height, 0px) + 40px));
  gap: 24px;
  text-align: left;
}
#main-world .world-section .section-era-badge,
#main-world .world-section .world-title,
#main-world .world-section .world-subtitle {
  grid-column: 1;
  text-align: left;
  margin-left: 0;
}
#main-world .world-section .world-title {
  font-family: var(--display) !important;
  font-style: italic !important;
  font-size: clamp(64px, 9vw, 136px) !important;
  font-weight: 400 !important;
  line-height: 1.03 !important;
  letter-spacing: -0.05em;
  text-transform: none;
}
#main-world .world-section .world-subtitle {
  max-width: none;
}
#main-world .world-section .vinyl-grid {
  grid-column: 1;
  grid-row: auto;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 0 40px;
}
#main-world .world-section .secret-badge {
  justify-self: start;
}
@media (max-width: 1100px) {
  #main-world .world-section {
    padding: 145px var(--gutter) max(180px, calc(var(--transport-height, 0px) + 40px));
    gap: 24px;
  }
  #main-world .world-section .world-title {
    font-size: clamp(64px, 9vw, 136px) !important;
  }
  #main-world .world-section .vinyl-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
    gap: 0 36px;
  }
}
@media (max-width: 700px) {
  #main-world .world-section,
  #main-world #paradise-ep {
    padding: 116px 24px max(calc(185px + env(safe-area-inset-bottom)), calc(var(--transport-height, 0px) + 40px));
    gap: 18px;
  }
  #main-world .world-section .world-title {
    font-size: clamp(64px, 9vw, 136px) !important;
  }
  #main-world .world-section .vinyl-grid {
    grid-template-columns: minmax(0, 1fr);
    gap: 0;
  }
}

/* Final polish: decorative intro only; existing controls and engine are retained. */
.intro-frame {
  inset: auto; top: 50%; right: 7%; width: min(50vw, 76vh);
  height: auto; aspect-ratio: 4 / 3; transform: translateY(-50%);
  background-image: none; filter: none; opacity: .85; overflow: hidden;
  pointer-events: none;
}
.intro-title-film { display: block; width: 100%; height: 100%; }
.enter-btn {
  color: var(--paper); border-bottom-color: #e5cfaa;
  background: linear-gradient(90deg, #dac09b15, #dac09b03);
  box-shadow: 0 8px 22px -16px #e5cfaa90;
  font-weight: 500;
  transition: color .3s, border-color .3s, box-shadow .3s, background .3s;
}
.enter-btn:hover, .enter-btn:focus-visible {
  color: #fff8e9; border-bottom-color: #fff0d4;
  background: linear-gradient(90deg, #dac09b25, #dac09b08);
  box-shadow: 0 10px 26px -15px #e5cfaaaf;
}
.enter-btn:focus-visible { outline: 1px solid #e5cfaa; outline-offset: 6px; }
@media (max-width: 700px) {
  .intro-frame { top: 18%; right: 9%; width: 68%; height: auto; aspect-ratio: 4 / 3; transform: none; opacity: .7; }
}
