#album-select-screen .as-card:nth-child(-n+7)::before {
  background-image: var(--cover-image); background-size: cover;
  background-position: var(--cover-focus); background-repeat: no-repeat;
}
/* Opacity keeps the existing hover response without scaling beyond the aperture. */
#album-select-screen .as-card:hover::before,
#album-select-screen .as-card:focus-visible::before { transform: none; }

/* Album palette compatibility; no geometry or engine changes. */
#main-world, #vinyl-player, .now-playing {
  --album-accent: var(--scene-accent);
  --album-bg: var(--scene);
}
#main-world .section-era-badge { color: var(--scene-detail, var(--scene-accent)); }
#vinyl-player #fav-btn { color: var(--scene-accent) !important; }
/* Canvas artwork is retained; noir's existing imagery is rendered monochrome. */
body:has(#uv:not([style*="display: none"])) #uv .section-atmosphere,
body:has(#uv:not([style*="display: none"])) #uv .vinyl-disc,
body:has(#uv:not([style*="display: none"])) #player-vinyl-canvas {
  filter: grayscale(1);
}
